import re
import sys

text = sys.stdin.read()
values = {}

pattern = re.compile(r"\b(a|b|c|d|TMP)\s*<-\s*(\d+|a|b|c|d|TMP)\b")

for match in pattern.finditer(text):
    target, source = match.groups()
    values[target] = int(source) if source.isdigit() else values[source]

print(
    "; ".join(
        f"{name} ?= {values[name]}"
        for name in ("a", "b", "c", "d", "TMP")
    ) + ";"
)
